import Image from "next/image";

// The supplied logo has dark-green lettering for light backgrounds. The dark variant swaps the lettering to sand
// so it stays legible on the site's dark header and footer. Both are generated by scripts/brand.mjs.
export function Logo({ className = "h-16", variant = "dark", priority = false }: { className?: string; variant?: "light" | "dark"; priority?: boolean }) {
  return (
    <Image
      src={variant === "dark" ? "/brand/atlas-logo-dark.webp" : "/brand/atlas-logo.webp"}
      alt="Atlas Private Tours: Discover Morocco your way"
      width={1200}
      height={653}
      sizes="(min-width:768px) 160px, 130px"
      priority={priority}
      className={`w-auto ${className}`}
    />
  );
}
